-- =============================================================================
-- 477 — LE CAHIER D'EXERCICES DE 5E (partie 6)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/5e/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 477 --niveau 5e --fichiers maths.n3,musique.n1,physique-chimie.n1 --suffixe 6 > supabase/contenu/477_exercices_5e_6.sql
--
-- 66 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   maths.n3                24 exercices · 8 chapitres
--   musique.n1               9 exercices · 3 chapitres
--   physique-chimie.n1      33 exercices · 11 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('aa054ed6-5670-5eaa-9c54-52e601153f2b'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La boîte de conserve de Mamie","competence":"calculer","situation":"Mamie range ses conserves. Sa boîte de haricots est un cylindre : une étiquette en papier, bien rectangulaire, en fait exactement le tour. Aide Inès à étudier cette boîte.","documents":[{"id":"boite","type":"schema","titre":"La boîte de conserve","largeur":320,"hauteur":240,"source":"Schéma non à l’échelle","elements":[{"forme":"chemin","d":"M80 70 L80 180 A80 22 0 0 0 240 180 L240 70 Z","ferme":true,"teinte":"gris","motif":"clair","id":"z1","zone":true},{"forme":"ellipse","cx":160,"cy":70,"rx":80,"ry":22,"teinte":"gris","motif":"plein","id":"z2","zone":true},{"forme":"ligne","de":[160,70],"a":[240,70],"id":"z3","zone":true,"epaisseur":3},{"forme":"texte","x":200,"y":57,"texte":"4 cm","taille":"normal","gras":true},{"forme":"ligne","de":[268,70],"a":[268,180],"fleche":"deux","id":"z4","zone":true},{"forme":"texte","x":296,"y":130,"texte":"11 cm","gras":true},{"forme":"texte","x":160,"y":226,"texte":"π ≈ 3,14","italique":true}]}],"questions":[{"enonce":"Touche le segment qui représente le **rayon** du disque de base.","aide":"Le rayon va du centre du disque jusqu’à son bord.","type":"zone","document":"boite","multiple":false},{"enonce":"L’étiquette fait exactement le tour de la boîte. Quelle est la **longueur** de cette bande de papier, en cm ? (π ≈ 3,14)","aide":"Déroulée, l’étiquette est un rectangle dont la longueur est le tour du disque de base, c’est-à-dire son périmètre.","type":"nombre","unite":"cm"},{"enonce":"Quel est le **volume** de la boîte, en cm³, arrondi à l’unité ? (π ≈ 3,14)","aide":"Volume du cylindre : aire du disque de base × hauteur, avec une aire de disque égale à π × R × R.","type":"nombre","unite":"cm³"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"Le rayon part du **centre** du disque de base et rejoint son bord : ici, 4 cm. Le segment vertical, lui, est la hauteur de la boîte."},{"cle":{"type":"nombre","valeur":25.12,"tolerance":0},"affichage":"25,12 cm","explication":"La surface latérale déroulée est un rectangle dont la longueur est le périmètre de la base : 2 × π × R = 2 × 3,14 × 4 = **25,12 cm**."},{"cle":{"type":"nombre","valeur":553,"tolerance":0},"affichage":"553 cm³","explication":"V = π × R² × h = 3,14 × 4 × 4 × 11 = 552,64 cm³, soit **553 cm³** à l’unité près."}]$ex$::jsonb),
  ('aa054ed6-5670-5eaa-9c54-52e601153f2b'::uuid, 2, 2, 10, 35, 5,
