  ('aa054ed6-5670-5eaa-9c54-52e601153f2b'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une cuve pour l’eau de pluie","competence":"modeliser","situation":"Le grand-père de Léa fabrique une cuve cylindrique pour récupérer l’eau de pluie du jardin. Elle n’a pas de couvercle. Il découpe la tôle d’après un patron : un rectangle et un disque.","documents":[{"id":"fiche","type":"fiche","modele":"etiquette","titre":"La fiche de fabrication","entete":"Cuve cylindrique","sousTitre":"Cuve ouverte, sans couvercle","emoji":"🪣","lignes":[{"texte":"Diamètre de la base","valeur":"1 m","id":"z1"},{"texte":"Hauteur","valeur":"1,2 m","id":"z2"},{"separateur":true},{"texte":"Valeur de π retenue","valeur":"3,14"}],"pied":"Fiche écrite pour l’exercice"},{"id":"patron","type":"figure","titre":"Le patron de la cuve","source":"Patron à l’échelle : 1 carreau = 25 cm","cadre":{"xmin":0,"xmax":15,"ymin":0,"ymax":11},"quadrillage":true,"points":[{"id":"A","x":1,"y":1,"position":"so"},{"id":"B","x":13.56,"y":1,"position":"se"},{"id":"C","x":13.56,"y":5.8,"position":"ne"},{"id":"D","x":1,"y":5.8,"position":"no"},{"id":"O","x":4,"y":7.8,"cache":true}],"segments":[{"id":"z3","de":"B","a":"C"}],"polygones":[{"id":"z5","sommets":["A","B","C","D"],"teinte":"bleu","motif":"clair"}],"cercles":[{"id":"z4","centre":"O","rayon":2,"teinte":"bleu"}],"textes":[{"x":12.1,"y":3.4,"texte":"1,2 m","teinte":"bleu"}]}],"questions":[{"enonce":"Touche la partie du patron qui s’enroule autour de la cuve pour former **sa paroi**.","aide":"La surface latérale d’un cylindre, une fois déroulée, est un rectangle.","type":"zone","document":"patron","multiple":false},{"enonce":"Quelle est la **longueur** du rectangle, en m ? (π ≈ 3,14)","aide":"Le rectangle fait exactement le tour du fond : sa longueur est le périmètre du disque.","type":"nombre","unite":"m"},{"enonce":"Combien de **litres** d’eau la cuve peut-elle contenir ? Attention, le rayon n’est pas le diamètre. (1 m³ = 1 000 L)","aide":"Le rayon est la moitié du diamètre : 0,5 m. Calcule d’abord le volume en m³.","type":"nombre","unite":"L"},{"enonce":"La cuve est ouverte : il faut la paroi et un seul disque de fond. Quelle **surface de tôle** faut-il, en m², arrondie au dixième ?","aide":"Paroi : 3,14 × 1,2. Fond : π × R², avec R = 0,5 m. Additionne les deux avant d’arrondir.","type":"nombre","unite":"m²"},{"enonce":"Son voisin veut une cuve de **rayon 1 m** (le double), avec la même hauteur 1,2 m. Son volume sera…","aide":"Calcule le volume de la grande cuve avec R = 1 m, puis compare à 0,942 m³.","type":"choix","options":[{"id":"a","texte":"multiplié par 4"},{"id":"b","texte":"multiplié par 2"},{"id":"c","texte":"identique"},{"id":"d","texte":"multiplié par 8"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z5"]},"explication":"La paroi de la cuve est la **surface latérale** : déroulée, elle forme le grand rectangle. Le disque est le fond."},{"cle":{"type":"nombre","valeur":3.14,"tolerance":0},"affichage":"3,14 m","explication":"Longueur du rectangle = périmètre du disque = π × diamètre = 3,14 × 1 = **3,14 m**."},{"cle":{"type":"nombre","valeur":942,"tolerance":0},"affichage":"942 L","explication":"R = 0,5 m. V = π × R² × h = 3,14 × 0,25 × 1,2 = 0,942 m³. Comme 1 m³ = 1 000 L, la cuve contient **942 L**."},{"cle":{"type":"nombre","valeur":4.6,"tolerance":0},"affichage":"4,6 m²","explication":"Paroi : 3,14 × 1,2 = 3,768 m². Fond : 3,14 × 0,5 × 0,5 = 0,785 m². Total : 4,553 m², soit **4,6 m²** au dixième près."},{"cle":{"type":"choix","ids":["a"]},"explication":"Avec R = 1 m : V = 3,14 × 1 × 1 × 1,2 = 3,768 m³, et 3,768 ÷ 0,942 = 4. Le rayon est au **carré** dans la formule : doubler R multiplie le volume par **4**."}]$ex$::jsonb),
  ('0663da05-a754-5e88-94c1-0c33cd7640fc'::uuid, 1, 1, 5, 20, 3,
