  ('0663da05-a754-5e88-94c1-0c33cd7640fc'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La passerelle du parc","competence":"raisonner","situation":"Sur le plan d’une passerelle, la main courante (d) et la rambarde (d′) sont parallèles. Une barre de renfort (s) les coupe en A et en B. L’angle ∠CAB mesure 62°.","documents":[{"id":"passerelle","type":"figure","titre":"La passerelle du parc","source":"Schéma réalisé pour l’exercice : (d) et (d′) sont parallèles","cadre":{"xmin":0,"xmax":10,"ymin":0,"ymax":7.5},"points":[{"id":"A","x":4.2,"y":2.2,"position":"se"},{"id":"B","x":5.795,"y":5.2,"position":"no"},{"id":"C","x":9,"y":2.2,"position":"n"},{"id":"E","x":0.9,"y":2.2,"position":"n"},{"id":"F","x":2.495,"y":5.2,"position":"s"},{"id":"G","x":9,"y":5.2,"position":"s"},{"id":"H","x":3.59,"y":1.052,"position":"o"},{"id":"K","x":6.452,"y":6.436,"position":"e"}],"droites":[{"par":["E","C"],"nom":"(d)"},{"par":["F","G"],"nom":"(d′)"},{"par":["H","K"],"nom":"(s)"}],"angles":[{"id":"z1","sommet":"A","de":"C","a":"B","mesure":"62°"},{"id":"z2","sommet":"A","de":"B","a":"E"},{"id":"z3","sommet":"B","de":"F","a":"A"},{"id":"z4","sommet":"B","de":"A","a":"G"},{"id":"z5","sommet":"B","de":"G","a":"K"}]}],"questions":[{"enonce":"Que mesure l’angle ∠FBA, en degrés ?","aide":"Compare ∠FBA et ∠CAB : de quel côté de (s) sont-ils, et par rapport aux deux droites ?","type":"nombre","unite":"°"},{"enonce":"Touche **tous** les angles tracés qui mesurent 118°.","aide":"Cherche les angles adjacents à un angle de 62° (ils forment avec lui un angle plat), ou leurs alternes-internes.","type":"zone","document":"passerelle","multiple":true},{"enonce":"Que mesure l’angle ∠GBK, en degrés ?","aide":"Compare ∠GBK et ∠CAB : ils sont à la même place, chacun à son point d’intersection.","type":"nombre","unite":"°"},{"enonce":"Quelle propriété permet d’affirmer que ∠GBK = ∠CAB ?","aide":"Regarde la position des deux angles : même place, chacun à une intersection différente.","type":"choix","options":[{"id":"a","texte":"Deux angles adjacents sur une droite sont supplémentaires"},{"id":"b","texte":"Les angles opposés par le sommet sont toujours égaux entre eux"},{"id":"c","texte":"Les correspondants sont égaux si les droites sont parallèles"},{"id":"d","texte":"La somme des angles d’un triangle est égale à 180°"}],"multiple":false}]}$ex$::jsonb,
