  ('4e4a9465-55d7-51be-92de-8f9113f15a47'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Les baguettes du cerf-volant","competence":"raisonner","situation":"Lila fabrique des cerfs-volants. Elle choisit trois baguettes dans sa boîte pour former les côtés d’un triangle. Mais toutes les combinaisons ne marchent pas !","documents":[{"id":"baguettes","type":"tableau","titre":"La boîte de baguettes de Lila","source":"Longueurs inventées pour l’exercice","colonnes":["Baguette","A","B","C","D","E"],"lignes":[["Longueur (cm)",30,40,50,70,100]],"enteteLignes":true}],"questions":[{"enonce":"Range chaque choix de trois baguettes : peut-on construire un triangle ?","aide":"Compare la plus longue baguette à la somme des deux autres.","type":"categories","categories":[{"id":"c0","texte":"Triangle possible"},{"id":"c1","texte":"Points alignés"},{"id":"c2","texte":"Triangle impossible"}],"items":[{"id":"i0","texte":"A, B et D"},{"id":"i1","texte":"A, C et E"},{"id":"i2","texte":"A, B et C"},{"id":"i3","texte":"B, C et D"}]},{"enonce":"Avec les baguettes A, B et C, quel est le **périmètre** du triangle, en cm ?","aide":"Additionne les trois longueurs lues dans le tableau.","type":"nombre","unite":"cm"},{"enonce":"Lila garde A (30 cm) et B (40 cm) et cherche une troisième baguette, de longueur entière en cm. Quelle est la **plus grande** longueur possible pour former un vrai triangle ?","aide":"Le plus long côté doit être strictement plus petit que la somme des deux autres : 30 + 40 = 70.","type":"nombre","unite":"cm"}]}$ex$::jsonb,
