   $ex${"titre":"La plaque triangulaire en équilibre","competence":"raisonner","situation":"Nina découpe une plaque de carton triangulaire ABC. Elle veut la poser en équilibre sur la pointe d’un crayon. Elle trace les trois médianes et note les dimensions de la plaque.","documents":[{"id":"plaque","type":"figure","titre":"Les médianes de la plaque","source":"Schéma à main levée : les longueurs ne sont pas respectées","cadre":{"xmin":0,"xmax":14,"ymin":0,"ymax":14},"points":[{"id":"A","x":5.954,"y":12.953,"position":"no"},{"id":"B","x":1,"y":1,"position":"so"},{"id":"C","x":13,"y":1,"position":"se"},{"id":"A1","x":7,"y":1,"position":"s","nom":"A′"},{"id":"B1","x":9.477,"y":6.977,"position":"ne","nom":"B′"},{"id":"C1","x":3.477,"y":6.977,"position":"no","nom":"C′"},{"id":"G","x":6.651,"y":4.984,"position":"se"}],"segments":[{"id":"z1","de":"A","a":"B"},{"id":"z2","de":"A","a":"C"},{"de":"B","a":"A1","codage":1},{"de":"A1","a":"C","codage":1},{"de":"C","a":"B1","codage":2},{"de":"B1","a":"A","codage":2},{"de":"A","a":"C1","codage":3},{"de":"C1","a":"B","codage":3},{"id":"z3","de":"A","a":"A1","style":"pointilles"},{"id":"z4","de":"B","a":"B1","style":"pointilles"},{"id":"z5","de":"C","a":"C1","style":"pointilles"}]},{"id":"fiche","type":"fiche","modele":"panneau","titre":"Fiche de la plaque","entete":"Plaque ABC en carton","emoji":"📐","lignes":[{"texte":"Côté [BC]","valeur":"10 cm"},{"texte":"Hauteur issue de A","valeur":"8 cm"},{"texte":"Médiane [AA′]","valeur":"12 cm"}],"pied":"Données inventées pour l’exercice"}],"questions":[{"enonce":"Touche le **centre de gravité** de la plaque, le point où elle tiendra en équilibre.","aide":"C’est le point de rencontre des trois médianes.","type":"zone","document":"plaque","multiple":false},{"enonce":"Quelle est la distance **AG**, en cm ? (G est aux deux tiers de la médiane en partant du sommet.)","aide":"Calcule les deux tiers de 12 cm : 12 ÷ 3 = 4, puis 4 × 2.","type":"nombre","unite":"cm"},{"enonce":"Nina veut suspendre la plaque horizontalement à un fil, en un seul point. Où doit-elle accrocher le fil ?","aide":"Il s’agit du point d’équilibre de la plaque.","type":"choix","options":[{"id":"a","texte":"Au point où se coupent les trois hauteurs"},{"id":"b","texte":"Au point où se coupent les médiatrices"},{"id":"c","texte":"Au sommet A de la plaque"},{"id":"d","texte":"Au point G, où se coupent les médianes"}],"multiple":false},{"enonce":"Quelle est l’**aire** de la plaque ABC, en cm² ? (aire = (base × hauteur) ÷ 2)","aide":"Prends [BC] comme base : la fiche donne sa longueur et la hauteur qui lui correspond.","type":"nombre","unite":"cm²"},{"enonce":"La médiane [AA′] coupe la plaque en deux triangles, ABA′ et AA′C. Quelle est l’**aire** du triangle ABA′, en cm² ?","aide":"Une médiane partage le triangle en deux triangles de même aire.","type":"nombre","unite":"cm²"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["G"]},"explication":"Les trois médianes se coupent en **G**, le centre de gravité : c’est là que la plaque tient en équilibre sur une pointe."},{"cle":{"type":"nombre","valeur":8,"tolerance":0},"affichage":"8 cm","explication":"AG = {{2/3}} de AA′ = {{2/3}} × 12 = **8 cm**. (Il reste GA′ = 4 cm.)"},{"cle":{"type":"choix","ids":["d"]},"explication":"Le point d’équilibre est le **centre de gravité**, à l’intersection des médianes."},{"cle":{"type":"nombre","valeur":40,"tolerance":0},"affichage":"40 cm²","explication":"Base BC = 10 cm, hauteur issue de A = 8 cm : aire = (10 × 8) ÷ 2 = **40 cm²**."},{"cle":{"type":"nombre","valeur":20,"tolerance":0},"affichage":"20 cm²","explication":"Une médiane coupe le triangle en deux triangles de **même aire** : 40 ÷ 2 = **20 cm²**."}]$ex$::jsonb),
