   $ex${"titre":"Le fanion de la régate","competence":"calculer","situation":"Sur le plan d’un fanion triangulaire, la couturière a noté deux angles : 66° en A et 51° en B. L’angle en C est effacé.","documents":[{"id":"fanion","type":"figure","titre":"Le plan du fanion","source":"Plan dessiné à l’échelle pour l’exercice","cadre":{"xmin":0,"xmax":10,"ymin":0,"ymax":8},"points":[{"id":"A","x":1,"y":1,"position":"so"},{"id":"B","x":9,"y":1,"position":"se"},{"id":"C","x":3.838,"y":7.374,"position":"n"}],"segments":[{"de":"A","a":"B"},{"de":"A","a":"C"},{"de":"B","a":"C"}],"angles":[{"id":"z1","sommet":"A","de":"B","a":"C","mesure":"66°"},{"id":"z2","sommet":"B","de":"C","a":"A","mesure":"51°"},{"id":"z3","sommet":"C","de":"A","a":"B","mesure":"?"}]}],"questions":[{"enonce":"Que mesure l’angle en C, en degrés ?","aide":"Dans un triangle, la somme des trois angles est toujours la même.","type":"nombre","unite":"°"},{"enonce":"Touche **le plus petit** des trois angles du triangle.","aide":"Compare 66°, 51° et l’angle que tu viens de calculer.","type":"zone","document":"fanion","multiple":false},{"enonce":"Comment s’appelle ce triangle, d’après ses angles ?","aide":"Regarde si l’un des angles est droit ou obtus.","type":"choix","options":[{"id":"a","texte":"Acutangle"},{"id":"b","texte":"Rectangle"},{"id":"c","texte":"Obtusangle"},{"id":"d","texte":"Équilatéral"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":63,"tolerance":0},"affichage":"63 °","explication":"La somme des angles d’un triangle vaut 180° : 180 − 66 − 51 = **63°**."},{"cle":{"type":"zone","ids":["z2"]},"explication":"Les trois angles mesurent 66°, 51° et 63° : le plus petit est celui de **51°**, en B."},{"cle":{"type":"choix","ids":["a"]},"explication":"Les trois angles (66°, 51°, 63°) sont **aigus** : le triangle est acutangle. Il n’est pas équilatéral : les angles ne valent pas tous 60°."}]$ex$::jsonb),
