   $ex${"titre":"Une erreur dans le carnet de l’architecte","competence":"raisonner","situation":"Un architecte note les angles de quatre triangles de sa maquette. Certaines mesures sont à retrouver, et l’une des lignes contient une erreur. Inès et Hugo cherchent laquelle.","documents":[{"id":"carnet","type":"tableau","titre":"Le carnet de l’architecte","source":"Mesures inventées pour l’exercice","colonnes":["Triangle","∠A","∠B","∠C"],"lignes":[["T1","54°","71°","?"],["T2","90°","38°","?"],["T3","105°","45°","40°"],["T4","?","65°","65°"]],"enteteLignes":true},{"id":"echange","type":"dialogue","modele":"sms","titre":"Le message d’Inès et Hugo","participants":[{"nom":"Inès","emoji":"👧","cote":"gauche"},{"nom":"Hugo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Inès","texte":"Pour T4, j’ai trouvé ∠A = 65°, puisque les deux autres angles font 65°."},{"qui":"Hugo","texte":"Attends… 65° + 65° + 65° = 195°. Ça ne fait pas 180° !"}]}],"questions":[{"enonce":"Dans le triangle T1, que mesure ∠C, en degrés ?","aide":"La somme des angles d’un triangle vaut 180°.","type":"nombre","unite":"°"},{"enonce":"Touche le nom du triangle qui **n’existe pas** : ses trois angles sont impossibles.","aide":"Additionne les trois angles de chaque triangle où ils sont tous connus.","type":"zone","document":"carnet","multiple":false},{"enonce":"Quelle est l’erreur d’Inès pour le triangle T4 ?","aide":"Que vaut la somme des trois angles ? Calcule le troisième angle avec cette somme.","type":"choix","options":[{"id":"a","texte":"Elle a recopié 65° au lieu de calculer 180° − 65° − 65°"},{"id":"b","texte":"Elle a cru que T4 était un triangle rectangle"},{"id":"c","texte":"Elle a additionné au lieu de retrancher les deux angles"},{"id":"d","texte":"Elle a oublié que la somme des angles vaut 90°"}],"multiple":false},{"enonce":"L’angle extérieur de T1 en C est le supplémentaire de ∠C. Quelle est sa mesure, en degrés ?","aide":"Tu peux soustraire ∠C à 180°, ou additionner les deux autres angles du triangle.","type":"nombre","unite":"°"},{"enonce":"Le triangle T2 a un angle droit en A. Que mesure ∠C, en degrés ?","aide":"Les deux angles aigus d’un triangle rectangle sont complémentaires.","type":"nombre","unite":"°"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":55,"tolerance":0},"affichage":"55 °","explication":"54 + 71 = 125, et 180 − 125 = **55°**."},{"cle":{"type":"zone","ids":["r2c0"]},"explication":"T3 : 105 + 45 + 40 = 190°, or la somme doit valoir 180°. **T3 est impossible**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le troisième angle ne se « recopie » pas : 180 − 65 − 65 = **50°**. T4 est un triangle isocèle de sommet A."},{"cle":{"type":"nombre","valeur":125,"tolerance":0},"affichage":"125 °","explication":"180 − 55 = 125°. On retrouve aussi 54 + 71 = **125°**, la somme des deux angles intérieurs non adjacents."},{"cle":{"type":"nombre","valeur":52,"tolerance":0},"affichage":"52 °","explication":"Les angles aigus sont complémentaires : 90 − 38 = **52°**. (Ou : 180 − 90 − 38 = 52°.)"}]$ex$::jsonb),
