   $ex${"titre":"La radio de Karvia et le film d’Emma","competence":"analyser-texte","situation":"Émilie lit un article sur un pays imaginaire, puis une conversation entre deux amis qui sortent d’un film. Dans les deux cas, la musique joue un rôle bien précis.","documents":[{"id":"karvia","type":"texte","genre":"article","titre":"Karvia : la radio d’État","auteur":"Article imaginé pour l’exercice","blocs":["Depuis le coup d’État, la radio n’a le droit de diffuser que des marches qui célèbrent le Général.","Le chanteur Mirek, dont les chansons se moquaient du régime, ne peut plus se produire : ses disques ont été retirés des magasins.","Chaque matin, les élèves chantent l’hymne du pays, pour se sentir membres d’un même peuple.","Avant d’être diffusée, chaque chanson doit être lue par un comité qui supprime les couplets jugés dangereux."]},{"id":"film","type":"dialogue","modele":"sms","participants":[{"nom":"Emma","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"🧑","cote":"droite"}],"repliques":[{"qui":"Emma","texte":"La musique devient grave et lente juste avant l’apparition du monstre."},{"qui":"Tom","texte":"Et j’ai adoré la valse légère pendant la bagarre !"},{"qui":"Emma","texte":"Quand le héros pleure, l’orchestre monte avec lui. Et la flûte de Luna revient à chaque fois qu’elle entre."}]}],"questions":[{"enonce":"Associe chaque fait de l’article au procédé de pouvoir qu’il illustre.","aide":"Relis chaque paragraphe : que fait le régime de la musique ?","type":"association","gauche":[{"id":"g0","texte":"Des marches qui célèbrent le Général"},{"id":"g1","texte":"Les disques de Mirek retirés"},{"id":"g2","texte":"L’hymne chanté chaque matin"},{"id":"g3","texte":"Un comité qui coupe des couplets"}],"droite":[{"id":"d0","texte":"Fabriquer l’unité"},{"id":"d1","texte":"Musique officielle"},{"id":"d2","texte":"Artiste interdit"},{"id":"d3","texte":"Censure"}]},{"enonce":"Range chaque passage du film selon le rôle de la musique.","aide":"Une musique peut prévenir d’un danger, aller à l’inverse de l’image ou amplifier l’émotion.","type":"categories","categories":[{"id":"c0","texte":"Elle anticipe"},{"id":"c1","texte":"Elle contredit"},{"id":"c2","texte":"Elle soutient"}],"items":[{"id":"i0","texte":"L’orchestre qui monte quand le héros pleure"},{"id":"i1","texte":"La musique grave avant le monstre"},{"id":"i2","texte":"La valse légère pendant la bagarre"}]},{"enonce":"Comment s’appelle un thème musical associé à un personnage, comme la flûte de Luna ? (un mot)","aide":"Ce mot vient de l’allemand et désigne un thème qui revient.","type":"texte"}]}$ex$::jsonb,
