   $ex${"titre":"Du disque au streaming","competence":"lire-graphique","situation":"Un magazine a mesuré, en pourcentage, comment les gens écoutent leur musique depuis 2005. Rayan lit le graphique et un extrait sur le fonctionnement d’une plateforme pour comprendre ce qui a changé.","documents":[{"id":"supports","type":"graphique","forme":"barres","titre":"Comment on écoute la musique","categories":["2005","2010","2015","2020"],"series":[{"nom":"CD et disques","valeurs":[85,65,35,10],"teinte":"gris"},{"nom":"Téléchargement","valeurs":[15,30,25,10],"teinte":"ambre"},{"nom":"Streaming","valeurs":[0,5,40,80],"teinte":"violet"}],"axeY":{"titre":"Part des écoutes","unite":"%","min":0,"max":100,"pas":20},"axeX":{"titre":"Année"},"valeurs":false,"source":"Chiffres imaginés pour l’exercice"},{"id":"melodia","type":"texte","genre":"article","titre":"Sur la plateforme Mélodia","auteur":"Texte écrit pour l’exercice","blocs":["Chaque matin, chaque abonné de Mélodia voit une liste « pour vous ».","Elle est composée par un algorithme, qui retient les titres écoutés jusqu’au bout et propose des titres proches.","Un artiste peu recommandé a donc peu de chances d’être découvert."]}],"questions":[{"enonce":"De combien de points la part du **streaming** a-t-elle augmenté entre 2015 et 2020 ?","aide":"Repère la série « Streaming » dans la légende, puis lis sa barre pour chacune des deux années.","type":"nombre","unite":"points"},{"enonce":"Touche **la première année** où le streaming dépasse les CD.","aide":"Compare, année après année, la barre du streaming et celle des CD.","type":"zone","document":"supports","multiple":false},{"enonce":"Associe chaque étape de l’industrie musicale à sa transformation.","aide":"Chaque étape change la façon dont on produit, découvre ou rémunère la musique.","type":"association","gauche":[{"id":"g0","texte":"Enregistrement"},{"id":"g1","texte":"Streaming"},{"id":"g2","texte":"Algorithmes"},{"id":"g3","texte":"Droit d’auteur"}],"droite":[{"id":"d0","texte":"Il rend tout disponible"},{"id":"d1","texte":"Il rémunère la création"},{"id":"d2","texte":"Ils décident de ce qu’on écoute"},{"id":"d3","texte":"Il fige et diffuse la musique"}]},{"enonce":"D’après l’extrait, que fait l’algorithme de Mélodia ?","aide":"Relis la phrase qui parle de la liste « pour vous ».","type":"choix","options":[{"id":"a","texte":"Il décide en partie de ce que chacun écoute"},{"id":"b","texte":"Il paye les artistes moins connus"},{"id":"c","texte":"Il choisit les titres au hasard"},{"id":"d","texte":"Il remplace l’enregistrement des artistes"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":40,"tolerance":0},"affichage":"40 points","explication":"Le streaming passe de 40 % en 2015 à 80 % en 2020 : 80 − 40 = **40 points**."},{"cle":{"type":"zone","ids":["k2"]},"explication":"En **2015**, le streaming (40 %) dépasse les CD (35 %) pour la première fois ; en 2010, il n’était qu’à 5 %."},{"cle":{"type":"association","paires":{"g1":"d0","g3":"d1","g2":"d2","g0":"d3"}},"explication":"L’**enregistrement** fige et diffuse, le **streaming** rend tout disponible, les **algorithmes** décident en partie de ce qu’on écoute, le **droit d’auteur** rémunère la création."},{"cle":{"type":"choix","ids":["a"]},"explication":"L’algorithme compose la liste « pour vous » : il **décide en partie de ce qu’on écoute**, donc de ce qu’on découvre."}]$ex$::jsonb),
  ('8bfc7fdd-cb95-55ad-9c0a-a1734702ab1d'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La vinaigrette de Zoé","competence":"analyser-document","situation":"Zoé prépare quatre mélanges pour un exposé. Elle note ce qu’elle voit dans chaque verre, sans rien filtrer ni chauffer.","documents":[{"id":"verres","type":"tableau","titre":"Les quatre verres de Zoé","colonnes":["Mélange","Ce qu’on voit"],"lignes":[["Vinaigrette (huile et vinaigre)","Deux couches : l’huile est au-dessus"],["Eau et sel","Un liquide limpide : le sel ne se voit plus"],["Eau et sable","Des grains de sable déposés au fond"],["Sirop dilué dans l’eau","Un liquide vert, partout pareil"]],"enteteLignes":true,"source":"Observations écrites pour l’exercice"}],"questions":[{"enonce":"Classe chaque mélange du tableau.","aide":"Un mélange homogène ne laisse voir qu’un seul constituant : relis la colonne « Ce qu’on voit ».","type":"categories","categories":[{"id":"c0","texte":"Homogène"},{"id":"c1","texte":"Hétérogène"}],"items":[{"id":"i0","texte":"Eau et sel"},{"id":"i1","texte":"Eau et sable"},{"id":"i2","texte":"Vinaigrette"},{"id":"i3","texte":"Sirop dilué"}]},{"enonce":"Touche l’observation d’un mélange qu’on peut séparer en le versant dans un filtre.","aide":"Un filtre retient les solides : cherche un mélange avec un solide au fond.","type":"zone","document":"verres","multiple":false},{"enonce":"Quelle technique permet de séparer l’huile et le vinaigre de la vinaigrette ?","aide":"On laisse reposer : un liquide va se placer au-dessus de l’autre.","type":"choix","options":[{"id":"a","texte":"La filtration"},{"id":"b","texte":"L’évaporation"},{"id":"c","texte":"La distillation"},{"id":"d","texte":"La décantation"}],"multiple":false}]}$ex$::jsonb,
