  ('7d0426c6-216e-519d-aa0e-31d31fe1d22c'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le méthane de la gazinière : compter les atomes","competence":"calculer","situation":"Dans la cuisine de Zoé, la gazinière brûle du méthane avec le dioxygène de l’air. Son professeur lui demande de vérifier que l’équation CH₄ + 2 O₂ → CO₂ + 2 H₂O est bien ajustée.","documents":[{"id":"atomes","type":"tableau","titre":"Le compte des atomes","colonnes":["Atome","À gauche (réactifs)","À droite (produits)"],"lignes":[["Carbone (C)",1,1],["Hydrogène (H)",4,"?"],["Oxygène (O)","?",4]],"enteteLignes":true,"source":"Équation de la combustion du méthane"},{"id":"masses","type":"tableau","titre":"Le bilan des masses (en g)","colonnes":["","CH₄","O₂","CO₂","H₂O"],"lignes":[["Avant",16,64,0,0],["Après",0,0,44,"?"]],"enteteLignes":true,"source":"Masses arrondies pour l’exercice"}],"questions":[{"enonce":"Combien d’atomes d’hydrogène y a-t-il à droite de l’équation, dans 2 H₂O ?","aide":"Chaque molécule d’eau contient 2 atomes d’hydrogène, et il y a 2 molécules.","type":"nombre"},{"enonce":"Pourquoi écrit-on le nombre 2 devant O₂ à gauche de l’équation ?","aide":"Compte les atomes d’oxygène à droite : dans CO₂ et dans 2 H₂O.","type":"choix","options":[{"id":"a","texte":"Pour rendre l’équation plus facile à lire"},{"id":"b","texte":"Pour indiquer qu’on utilise deux fois plus de gaz que d’eau"},{"id":"c","texte":"Pour montrer qu’il y a deux atomes dans la molécule de méthane"},{"id":"d","texte":"Pour avoir autant d’atomes d’oxygène à gauche qu’à droite"}],"multiple":false},{"enonce":"Ajuste l’équation de la formation de l’eau.","aide":"Compte les atomes d’hydrogène à gauche : 2 H₂ en contient 4.","type":"trous","segments":["2 H₂ + O₂ → ",0," H₂O"],"banque":["3","1","2","4"]},{"enonce":"D’après le bilan des masses, quelle masse d’eau se forme ?","aide":"La masse totale se conserve : masse avant = masse après.","type":"nombre","unite":"g"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4","explication":"2 × 2 = **4 atomes** d’hydrogène à droite, comme à gauche : l’hydrogène est conservé."},{"cle":{"type":"choix","ids":["d"]},"explication":"À droite il y a 2 + 2 = 4 atomes d’oxygène ; **2 O₂** en donne aussi 4 à gauche. Le nombre sert à **ajuster** l’équation."},{"cle":{"type":"trous","trous":[["2"]]},"affichage":"2","explication":"À gauche : 4 atomes de H et 2 atomes de O. À droite, **2 H₂O** donne bien 4 H et 2 O."},{"cle":{"type":"nombre","valeur":36,"tolerance":0},"affichage":"36 g","explication":"Avant : 16 + 64 = 80 g. Après : 44 + masse d’eau = 80 g, donc **36 g** d’eau (loi de Lavoisier)."}]$ex$::jsonb),
