e seule espèce.","type":"association","gauche":[{"id":"g0","texte":"Précipité vert avec la soude"},{"id":"g1","texte":"Précipité blanc qui noircit avec le nitrate d’argent"},{"id":"g2","texte":"Sulfate de cuivre anhydre qui devient bleu"},{"id":"g3","texte":"Détonation à l’approche d’une flamme"}],"droite":[{"id":"d0","texte":"Du dihydrogène"},{"id":"d1","texte":"Des ions fer II"},{"id":"d2","texte":"De l’eau"},{"id":"d3","texte":"Des ions chlorure"}]},{"enonce":"Que doit écrire Inès pour le test 2 dans son compte rendu ?","aide":"Ne conclus jamais par une couleur.","type":"choix","options":[{"id":"a","texte":"La solution contient des ions chlorure"},{"id":"b","texte":"Le nitrate d’argent est un précipité"},{"id":"c","texte":"Le précipité est blanc"},{"id":"d","texte":"La solution est noircie par la lumière"}],"multiple":false}]}$ex$::jsonb,
