   $ex${"titre":"Du sel de cuisine aux ions","competence":"lire-tableau","situation":"Mathis dissout du sel dans de l’eau. Son professeur lui donne un tableau pour s’y retrouver parmi les ions.","documents":[{"id":"ions","type":"tableau","titre":"Quelques ions","colonnes":["Ion","Symbole","Charge"],"lignes":[["Ion sodium","Na⁺","1 charge positive"],["Ion chlorure","Cl⁻","1 charge négative"],["Ion cuivre II","Cu²⁺","2 charges positives"],["Ion hydroxyde","OH⁻","1 charge négative"]],"enteteLignes":true,"source":"Tableau de référence"}],"questions":[{"enonce":"Classe chaque ion.","aide":"Un cation est chargé positivement, un anion négativement.","type":"categories","categories":[{"id":"c0","texte":"Cation"},{"id":"c1","texte":"Anion"}],"items":[{"id":"i0","texte":"Ion hydroxyde"},{"id":"i1","texte":"Ion cuivre II"},{"id":"i2","texte":"Ion sodium"},{"id":"i3","texte":"Ion chlorure"}]},{"enonce":"Combien d’électrons l’atome de cuivre a-t-il perdus pour devenir l’ion Cu²⁺ ?","aide":"Le nombre de charges est écrit en exposant.","type":"nombre"},{"enonce":"Une solution d’eau salée est-elle chargée électriquement dans son ensemble ?","aide":"Compare le nombre d’ions Na⁺ et d’ions Cl⁻ pour chaque grain de sel dissous.","type":"choix","options":[{"id":"a","texte":"Non : il y a autant de charges positives que négatives"},{"id":"b","texte":"Oui : elle est positive car le sel est un cation"},{"id":"c","texte":"Oui : elle est négative à cause des ions chlorure"},{"id":"d","texte":"Oui : elle est positive à cause des ions sodium"}],"multiple":false}]}$ex$::jsonb,
